#!/bin/bash
# Prints the three most frequent IPs in access.log, most frequent first,
# ties broken by first appearance in the log.
awk '
{
    count[$1]++
    if (!seen[$1]++) order[++n] = $1
}
END {
    best = 0
    for (i = n; i >= 1; i--)
        if (count[order[i]] > best) best = count[order[i]]
    for (t = 1; t <= 3; t++) {
        for (j = 1; j <= n; j++) {
            if (count[order[j]] == best) {
                print order[j]
                best--
                break
            }
        }
    }
}
' access.log

